/**
 * Constants shared by the browser upload client and the server chunk store.
 * Keep this file free of Node-only imports.
 */

/** Size of each upload chunk. Both sides MUST agree, so it lives here. */
export const CHUNK_SIZE = 16 * 1024 * 1024; // 16MB

/** Upload ids are random UUIDs generated by the client. */
export const UPLOAD_ID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
